From 975658ac4aded022c9eafd007571883cf8d3fc6d Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 01:14:43 +0100
Subject: [PATCH] kioworkers/desktop: watch for trashrc being created

Trash links on the desktop update their icon when trashrc changes, but
watching it failed silently when the file didn't exist yet, as for a new
user who never trashed anything. Watch the config folder until it does.

BUG: 524339
---
 kioworkers/desktop/desktopnotifier.cpp | 33 ++++++++++++++++++++++----
 kioworkers/desktop/desktopnotifier.h   |  1 +
 2 files changed, 29 insertions(+), 5 deletions(-)

diff --git a/kioworkers/desktop/desktopnotifier.cpp b/kioworkers/desktop/desktopnotifier.cpp
index b76be9ef51..722b8c08df 100644
--- a/kioworkers/desktop/desktopnotifier.cpp
+++ b/kioworkers/desktop/desktopnotifier.cpp
@@ -27,8 +27,8 @@ DesktopNotifier::DesktopNotifier(QObject *parent, const QList<QVariant> &)

     watcher = new QFileSystemWatcher(this);
     watcher->addPaths(QStringList{QStandardPaths::writableLocation(QStandardPaths::DesktopLocation),
-                                  QStandardPaths::writableLocation(QStandardPaths::ConfigLocation) + u"/trashrc",
                                   QStandardPaths::writableLocation(QStandardPaths::ConfigLocation) + QStringLiteral("/user-dirs.dirs")});
+    watchTrashrc();

     connect(watcher, &QFileSystemWatcher::fileChanged, this, &DesktopNotifier::dirty);
     connect(watcher, &QFileSystemWatcher::directoryChanged, this, &DesktopNotifier::dirty);
@@ -39,9 +39,34 @@ void DesktopNotifier::watchDir(const QString &path)
     watcher->addPath(path);
 }

+void DesktopNotifier::watchTrashrc()
+{
+    const QString configPath = QStandardPaths::writableLocation(QStandardPaths::ConfigLocation);
+    const QString trashrcPath = configPath + u"/trashrc";
+
+    if (watcher->files().contains(trashrcPath)) {
+        return;
+    }
+
+    // trashrc only exists once something has been trashed, so until then watch
+    // its directory to notice when it gets created
+    if (watcher->addPath(trashrcPath)) {
+        if (watcher->directories().contains(configPath)) {
+            watcher->removePath(configPath);
+        }
+    } else if (!watcher->directories().contains(configPath)) {
+        watcher->addPath(configPath);
+    }
+}
+
 void DesktopNotifier::dirty(const QString &path)
 {
-    if (path == QStandardPaths::writableLocation(QStandardPaths::ConfigLocation) + u"/trashrc") {
+    if (path == QStandardPaths::writableLocation(QStandardPaths::ConfigLocation)) {
+        // Waiting for trashrc to be created, see watchTrashrc()
+        if (QFile::exists(path + u"/trashrc")) {
+            dirty(path + u"/trashrc");
+        }
+    } else if (path == QStandardPaths::writableLocation(QStandardPaths::ConfigLocation) + u"/trashrc") {
         QList<QUrl> trashUrls;

         // Check for any .desktop file linking to trash:/ to update its icon
@@ -57,9 +82,7 @@ void DesktopNotifier::dirty(const QString &path)
             org::kde::KDirNotify::emitFilesChanged(trashUrls);
         }

-        if (!watcher->files().contains(path)) {
-            watcher->addPath(path);
-        }
+        watchTrashrc();
     } else if (path == QStandardPaths::writableLocation(QStandardPaths::ConfigLocation) + QStringLiteral("/user-dirs.dirs")) {
         checkDesktopLocation();

diff --git a/kioworkers/desktop/desktopnotifier.h b/kioworkers/desktop/desktopnotifier.h
index 3640b8e723..9b60174405 100644
--- a/kioworkers/desktop/desktopnotifier.h
+++ b/kioworkers/desktop/desktopnotifier.h
@@ -28,6 +28,7 @@ private Q_SLOTS:

 private:
     void checkDesktopLocation();
+    void watchTrashrc();

     QFileSystemWatcher *watcher;
     QUrl m_desktopLocation;
